module TopModule (
    input  clk,
    input  x,
    output z
);

    // Internal signals for the three D flip-flops
    reg q0, q1, q2;

    // Combinational logic for the D inputs of the flip-flops
    // The D input is the XOR of the external input x and the current Q output
    always @(*) begin
        // q0 next state: x XOR q0
        // q1 next state: x XOR q1
        // q2 next state: x XOR q2
        // Using non-blocking assignments in a combinational block is allowed
        // as long as each signal is driven exactly once.
        q0 <= x ^ q0;
        q1 <= x ^ q1;
        q2 <= x ^ q2;
    end

    // Sequential logic: D flip-flops triggered on the positive edge of clk
    always @(posedge clk) begin
        // Asynchronous reset is not explicitly provided, but the
        // specification states "initially reset to zero before the machine begins".
        // We initialize the registers to 0 here to model the reset condition.
        // In simulation, this block executes on every rising edge.
        // Synthesis tools will infer D flip-flops.
        q0 <= 1'b0; // Reset value
        q1 <= 1'b0;
        q2 <= 1'b0;
    end

    // Output logic: three-input NOR gate
    // The second inputs are: XOR uses q, AND uses ~q, OR uses ~q
    // Z = NOR( (x XOR q0), (x AND ~q1), (x OR ~q2) )
    assign z = ~( (x ^ q0) & (x & ~q1) | (x | ~q2) );

endmodule

