        next_byte_count = byte_count;
        next_shift_reg = shift_reg;
        next_done      = 1'b0;

        case (state)
            IDLE: begin
                if (in[3]) begin
                    // Found byte 1 of a message
                    next_state     = BYTE1;
                    next_byte_count = 1;
                    next_shift_reg = {24{1'b0}};       // clear shift register
                    next_shift_reg[23:16] = in;       // store first byte
                    next_done      = 1'b0;            // not done yet
                end else begin
                    // Keep looking, output stays unchanged (don't-care)
                    next_state = IDLE;
                end
            end

            BYTE1: begin
                // Wait for byte 2
                next_state = BYTE2;
                next_shift_reg = {shift_reg[15:0], in};  // shift in second byte at [15:8]
                next_byte_count = 2;
                next_done      = 1'b0;
            end

            BYTE2: begin
                // Wait for byte 3
                next_state = BYTE3;
                next_shift_reg = {shift_reg[7:0], in};   // shift in third byte at [7:0]
                next_byte_count = 3;
                next_done      = 1'b0;
            end

            BYTE3: begin
                // Third byte received – assert done in next cycle
                next_state     = IDLE;
                next_byte_count = 0;
                next_shift_reg = {24{1'b0}};
                next_done      = 1'b1;  // done asserted this cycle
            end

            default: next_state = IDLE;
        endcase
    end

    // Output assignment: out_bytes valid when done is asserted
    // (registered out_bytes follows shift_reg)
    always @(posedge clk) begin
        if (reset) begin
            out_bytes <= 0;
        end else begin
            out_bytes <= shift_reg;
        end
    end

endmodule

