module TopModule (
    input  clk,
    input  areset,
    input  bump_left,
    input  bump_right,
    input  ground,
    input  dig,
    output walk_left,
    output walk_right,
    output aaah,
    output digging
);

    // State encoding
    typedef enum logic [2:0] {
        WALK_LEFT   = 3'b000,
        WALK_RIGHT  = 3'b001,
        FALLING     = 3'b010,
        DIGGING     = 3'b011,
        SPLATTERED  = 3'b100
    } state_t;

    state_t state, next_state;

    // Outputs: Moore machine — outputs are registered, based on state
    assign walk_left   = (state == WALK_LEFT);
    assign walk_right  = (state == WALK_RIGHT);
    assign aaah        = (state == FALLING);
    assign digging     = (state == DIGGING);

    // State register (positive-edge triggered, asynchronous active-high reset)
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            state <= WALK_LEFT;
        end else begin
            state <= next_state;
        end
    end

    // Direction register: stores the walking direction before a fall or dig
    logic walk_dir; // 1 = right, 0 = left
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            walk_dir <= 1'b0;
        end else begin
            case (state)
                WALK_LEFT:    walk_dir <= 1'b0;
                WALK_RIGHT:   walk_dir <= 1'b1;
                default:      walk_dir <= walk_dir;
            endcase
        end
    end

    // Falling-cycle counter (5 bits: 0 to 21+)
    logic [4:0] fall_cnt;
    always_ff @(posedge clk or posedge areset) begin
        if (areset) begin
            fall_cnt <= 0;
        end else begin
            case (state)
                WALK_LEFT, WALK_RIGHT: begin
                    if (!ground) begin
                        fall_cnt <= 1; // just fell
                    end else begin
                        fall_cnt <= 0;
                    end
                end

                FALLING: begin
                    if (ground) begin
                        // ground just reappeared; keep the count for splatter check
                    end else begin
                        fall_cnt <= fall_cnt + 1'b1;
                    end
                end

                DIGGING: begin
                    if (!ground) begin
                        fall_cnt <= fall_cnt + 1'b1;
                    end else begin
                        fall_cnt <= 0;
                    end
                end

                SPLATTERED: begin
                    fall_cnt <= 0;
                end
            endcase
        end
    end

    // Next-state logic (combinational)
    always_comb begin
        next_state = state; // default: stay in current state

        case (state)
            WALK_LEFT: begin
                if (!ground) begin
                    // Start falling; direction preserved for when ground returns
                    next_state = FALLING;
                end else if (dig && !bump_left && !bump_right) begin
                    // Dig only when walking on ground, not bumped
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    // Switch direction when bumped (both sides still switches)
                    next_state = (bump_right) ? WALK_LEFT : WALK_RIGHT;
                end
                // else stay WALK_LEFT
            end

            WALK_RIGHT: begin
                if (!ground) begin
                    next_state = FALLING;
                end else if (dig && !bump_left && !bump_right) begin
                    next_state = DIGGING;
                end else if (bump_left || bump_right) begin
                    next_state = (bump_left) ? WALK_RIGHT : WALK_LEFT;
                end
                // else stay WALK_RIGHT
            end

            FALLING: begin
                if (ground) begin
                    if (fall_cnt > 20) begin
                        next_state = SPLATTERED;
                    end else begin
                        // Resume walking in the same direction as before the fall
                        if (walk_dir)
                            next_state = WALK_RIGHT;
                        else
                            next_state = WALK_LEFT;
                    end
                end
                // else stay FALLING
            end

            DIGGING: begin
                if (!ground) begin
                    // Reached the other side while digging -> fall
                    next_state = FALLING;
                end else if (!dig) begin
                    // Dig command removed -> stop digging, resume walking
                    if (walk_dir)
                        next_state = WALK_RIGHT;
                    else
                        next_state = WALK_LEFT;
                end
                // else stay DIGGING
            end

            SPLATTERED: begin
                // stay SPLATTERED (forever)
            end
        endcase
    end

endmodule

